package com.purchasing.service;
import com.purchasing.entity.*; import com.purchasing.repository.*; import org.springframework.stereotype.Service; import java.math.BigDecimal;
@Service public class PurchasingTools { final PurchaseOrderRepository orders; public PurchasingTools(PurchaseOrderRepository o){orders=o;} public int getProductInventory(Product p){return p.currentInventory;} public int getExpectedDemand(Product p){return p.expectedDemand;} public int getOpenPurchaseOrders(Product p){Integer q=orders.openQuantity(p.id);return q==null?0:q;} public Supplier getSupplierInformation(Supplier s){return s;} public BigDecimal getBudget(){return new BigDecimal("12000.00");} public int getStorageCapacity(Product p){return p.storageCapacity;} public BigDecimal calculatePurchaseCost(Product p,int q){return p.unitCost.multiply(BigDecimal.valueOf(q));} }
